/** True only for a parseable SVG document; rejects HTML fallbacks served with status 200. */
export function isSvgDocument(text: string): boolean {
  if (!/^\s*(<\?xml[^>]*>\s*)?<svg[\s>]/i.test(text)) return false
  if (typeof DOMParser === 'undefined') return true
  const doc = new DOMParser().parseFromString(text, 'image/svg+xml')
  return doc.documentElement.nodeName === 'svg' && doc.getElementsByTagName('parsererror').length === 0
}
